    ts('captured_method='        + hit.method);
    ts('captured_url='           + hit.url);
    ts('captured_host_header='   + hit.host);
    ts('captured_authorization=' + hit.auth);
    ts('pat_in_header='          + (hit.auth === 'Bearer ' + SERVER_PAT ? 'YES' : 'NO'));
