  ts('poc_start');
  ts('pkg=@contentful/mcp-tools@0.4.1');
  ts('pkg=@contentful/mcp-server@1.7.15');
  ts('vuln_files=exportSpace.ts:126-141,importSpace.ts:103-119');
  ts('cwe=CWE-918,CWE-441');
